package com.buildertoolbox.client.utils.render.color; public class Color {public int r,g,b,a; public Color(int r,int g,int b){this(r,g,b,255);} public Color(int r,int g,int b,int a){this.r=r;this.g=g;this.b=b;this.a=a;} public Color(Color c){this(c.r,c.g,c.b,c.a);} public void validate(){r=Math.clamp(r,0,255);g=Math.clamp(g,0,255);b=Math.clamp(b,0,255);a=Math.clamp(a,0,255);} public int getPacked(){return a<<24|r<<16|g<<8|b;} }